@@ -0,0 +1,133 @@
+package strategy
+
+import (
+	"context"
+	"fmt"
+	"log/slog"
+
+	"github.com/entireio/cli/cmd/entire/cli/logging"
+	"github.com/entireio/cli/cmd/entire/cli/proclive"
+)
+
+// findSessionsForCommitLinking resolves which sessions a commit belongs to:
+// the union of the worktree-matched set (a commit captures the worktree's
+// content, so every session with pending content here belongs in it —
+// concurrent sessions interleave by design) and the identity-matched session
+// when the committing process's ancestry names one that worktree matching
+// missed. There is no precedence between the two — an identity hit must
+// never suppress worktree matches, or concurrent same-worktree sessions
+// would drop out of the commit. The identity union is what makes an
+// agent-made commit immune to worktree bookkeeping drift: an agent
+// committing in a sibling worktree still links to its own session
+// (guest-linked), where path matching alone found nothing or declined as
+// ambiguous.
+//
+// This is also the only place the multi-worktree ambiguity decline is
+// surfaced to the user: the hint fires only when the FINAL set is empty, so
+// a commit rescued by identity matching never sees a false "none was
+// linked", and amend/post-rewrite paths (which call findSessionsForWorktree
+// directly) stay silent.
+func (s *ManualCommitStrategy) findSessionsForCommitLinking(ctx context.Context, worktreePath string) ([]*SessionState, error) {
+	allStates, err := s.listAllSessionStates(ctx)
+	if err != nil {
+		// Identity matching below needs the same listing, so nothing can
+		// rescue this; report it to the caller (hooks log and skip).
+		return nil, err
+	}
+	sessions, ambiguous := s.findSessionsForWorktreeFromStates(ctx, allStates, worktreePath)
+	if guest := s.findSessionByCommitAncestry(ctx, allStates); guest != nil && !linkingSetContains(sessions, guest.SessionID) {
+		sessions = append(sessions, guest)
+	}
+	if ambiguous && len(sessions) == 0 {
+		fmt.Fprintln(stderrWriter,
+			"[entire] Agent sessions in several other worktrees could match this commit; none was linked. Run 'entire session adopt' in this worktree to link future commits to your session.")
+	}
+	return sessions, nil
+}
+
+func linkingSetContains(states []*SessionState, id string) bool {
+	for _, st := range states {
+		if st.SessionID == id {
+			return true
+		}
+	}
+	return false
+}
+
+// findSessionByCommitAncestry attributes the running commit to the session
+// whose recorded owner process is an ancestor of this hook process. The
+// owner is the proclive.Identity that captureSessionOwner already persists
+// on every turn start (SessionState.Owner) — the same fingerprint liveness
+// checks use, carrying host, boot, and start-time guards so a recycled PID
+// or an identity recorded on another machine can never match. A commit hook
+// whose ancestry contains a session's owner was spawned (however indirectly)
+// by that session's agent, in whatever worktree the commit happens.
+//
+// When owners at different depths of the ancestry both match — a nested
+// agent and the outer agent that spawned it — the nearest ancestor wins: the
+// process closest to the commit is its author. Recency only breaks ties
+// within one depth (the same agent process hosting several sessions over its
+// lifetime, e.g. after a resume): there the most recently interacting
+// session wins — the one whose turn this commit concludes. Imported sessions
+// are historical records and adopted-away tombstones belong to another
+// store; neither ever matches. Returns nil when no session's owner is in our
+// ancestry (the linking set is then the worktree-matched sessions alone) —
+// including on platforms where proclive cannot introspect processes
+// (Windows), which deliberately fall back to worktree matching rather than
+// trusting unverifiable ancestry.
+//
+// The ancestry is snapshotted once (proclive.CurrentAncestry) and every
+// candidate matched in memory: this runs in the commit hook with one state
+// file per session in the shared store, so a per-candidate walk would repeat
+// the hostname/boot/proc reads dozens of times per commit.
+func (s *ManualCommitStrategy) findSessionByCommitAncestry(ctx context.Context, states []*SessionState) *SessionState {
+	ancestry, ok := proclive.CurrentAncestry()
+	if !ok {
+		return nil
+	}
+	var best *SessionState
+	bestDepth := -1
+	for _, state := range states {
+		if state.Kind.IsImported() || state.AdoptedIntoWorktreePath != "" || state.Owner == nil {
+			continue
+		}
+		depth := ancestry.Depth(*state.Owner)
+		if depth < 0 {
+			continue
+		}
+		if best == nil || depth < bestDepth || (depth == bestDepth && interactedAfter(state, best)) {
+			best, bestDepth = state, depth
+		}
+	}
+	if best != nil {
+		logging.Debug(logging.WithComponent(ctx, "checkpoint"),
+			"commit attributed to session by process ancestry",
+			slog.String("session_id", best.SessionID),
+			slog.Int("owner_pid", best.Owner.PID),
+			slog.String("owner_name", best.Owner.Name),
+		)
+	}
+	return best
+}
+
+// isSessionHomeWorktree reports whether worktreePath — the commit's worktree,
+// already resolved by the hook entry point — is the one the session is
+// recorded in. Worktree-coupled state (BaseCommit, shadow-branch content and
+// deletion) may only be mutated from the session's home worktree; a
+// guest-linked commit elsewhere condenses and links without moving it. A
+// pure comparison by design: an earlier version re-resolved the worktree
+// here and read resolution failure as "home", which would have mutated a
+// guest session's state in exactly the way the gate exists to prevent.
+func isSessionHomeWorktree(worktreePath string, state *SessionState) bool {
+	return worktreePath == "" || state.WorktreePath == "" || state.WorktreePath == worktreePath
+}
+
+func interactedAfter(a, b *SessionState) bool {
+	if a.LastInteractionTime == nil {
+		return false
+	}
+	if b.LastInteractionTime == nil {
+		return true
+	}
+	return a.LastInteractionTime.After(*b.LastInteractionTime)
+}

// Package proclive captures a process's identity (PID plus a start-time
// fingerprint) and later reports whether that exact process is still alive.
//
// It exists to detect agent sessions left in an ACTIVE state when the owning
// process went away — a clean exit, a crash, a kill, a closed terminal, or a
// reboot — without firing a SessionStop hook. Recording the owner's identity at
// turn start lets `entire status` / `entire doctor` notice the process is gone
// immediately, instead of waiting out a coarse inactivity timeout.
//
// This package is a leaf: it imports only the standard library and
// golang.org/x/sys/unix. It must NOT import session, strategy, agent, or cli,
// so those packages can depend on it without an import cycle.
package proclive

import (
	"errors"
	"os"
	"strings"
)

// Liveness is the result of checking a recorded process Identity.
type Liveness int

const (
	// LivenessUnknown means liveness could not be determined: the identity is
	// empty, was recorded on another host, or the platform cannot introspect
	// processes. Callers should fall back to a time-based heuristic.
	LivenessUnknown Liveness = iota
	// LivenessAlive means the recorded process is still running.
	LivenessAlive
	// LivenessDead means the recorded process is gone (exited, killed, or the
	// machine rebooted) or its PID has been reused by a different process.
	LivenessDead
)

func (l Liveness) String() string {
	switch l {
	case LivenessAlive:
		return "alive"
	case LivenessDead:
		return "dead"
	case LivenessUnknown:
		return "unknown"
	default:
		return "unknown"
	}
}

// Identity fingerprints the process that owns a session turn. It is persisted
// in session state and later passed to Check. The zero value means "no owner
// recorded" and always yields LivenessUnknown.
type Identity struct {
	// PID is the operating-system process id of the owner.
	PID int `json:"pid"`
	// Start is an opaque, per-platform process start-time fingerprint. It need
	// only be stable for the process lifetime and distinct across PID reuse
	// within a single boot; the Boot guard invalidates it across reboots.
	Start string `json:"start"`
	// Boot identifies the current OS boot. A mismatch at check time means the
	// machine rebooted, so the recorded PID cannot still be the same process.
	Boot string `json:"boot,omitempty"`
	// Host is the hostname where the identity was recorded. PIDs are only
	// meaningful on their own machine, so a mismatch yields Unknown.
	Host string `json:"host,omitempty"`
	// Name is the owning process's executable name (comm). Diagnostic only.
	Name string `json:"name,omitempty"`
}

var (
	// errProcessGone is returned by procStat when no process with the given PID
	// exists. Check maps it to LivenessDead.
	errProcessGone = errors.New("proclive: process not found")
	// errUnsupported is returned by the per-platform seam when the OS cannot be
	// introspected (e.g. Windows). Check maps it to LivenessUnknown.
	errUnsupported = errors.New("proclive: unsupported platform")
)

// maxAncestorDepth bounds the ResolveOwner walk so a pathological or cyclic
// process tree can never loop or hang.
const maxAncestorDepth = 12

// transientNames are process names that are never the long-lived session owner:
// our own hook binary, the shells agents commonly use to exec hooks, and the Go
// toolchain (a `go run`-launched hook has a short-lived `go` parent that would
// otherwise be recorded as the owner and exit immediately). The walk skips
// past these to reach the real agent process. Note that interpreter runtimes
// (node, bun, python) are deliberately absent — for several agents the runtime
// IS the long-lived agent, so treating it as transient would skip the real owner.
var transientNames = map[string]bool{
	"entire": true,
	"sh":     true,
	"bash":   true,
	"zsh":    true,
	"dash":   true,
	"fish":   true,
	"ash":    true,
	"ksh":    true,
	"env":    true,
	"go":     true,
}

func isTransient(name string) bool {
	return transientNames[strings.ToLower(strings.TrimSpace(name))]
}

// ResolveOwner walks up the process tree from the current process and returns
// the Identity of the first ancestor that is not our own hook binary or a
// shell — i.e. the long-lived agent that owns this session.
//
// It returns (zero, false) when no such ancestor can be determined: an
// unsupported platform, a truncated/looping tree, or only transient ancestors.
// In that case the caller should record no owner and let liveness degrade to
// the time-based fallback. Resolving to nothing is always safer than recording
// a guessed PID, which could later be (mis)read as a live or dead owner.
func ResolveOwner() (Identity, bool) {
	// The host guard is essential — a PID is only meaningful on the machine that
	// recorded it — so if the hostname can't be determined, record no owner
	// rather than an unguarded one that Check could later (mis)classify as
	// alive/dead across machines. Boot is a best-effort secondary guard; an
	// empty value just disables it (darwin records none — see bootID there).
	host, err := os.Hostname()
	if err != nil || host == "" {
		return Identity{}, false
	}
	boot, err := bootID()
	if err != nil {
		boot = ""
	}

	// Walk up from our own process, reading each ancestor exactly once: procStat
	// returns its parent (to continue the walk), its name (to skip shells and our
	// own binary), and its start fingerprint (to record).
	candidate, _, _, err := procStat(os.Getpid())
	if err != nil {
		return Identity{}, false
	}
	for range maxAncestorDepth {
		if candidate <= 1 {
			return Identity{}, false
		}
		parent, name, start, err := procStat(candidate)
		if err != nil {
			return Identity{}, false
		}
		if !isTransient(name) {
			return Identity{PID: candidate, Start: start, Boot: boot, Host: host, Name: name}, true
		}
		candidate = parent
	}
	return Identity{}, false
}

// Check reports whether the process recorded in id is still alive.
//
// Precedence: an empty identity or a host mismatch is Unknown (cannot judge); a
// boot mismatch means a reboot, so the process is Dead; a missing PID or a
// start-fingerprint mismatch (PID reuse) is Dead; otherwise Alive. An
// unsupported platform is always Unknown so callers fall back to a timeout.
func Check(id Identity) Liveness {
	if id.PID <= 0 {
		return LivenessUnknown
	}
	if id.Host != "" {
		// Can't confirm we're on the recording host → can't trust its PIDs.
		host, err := os.Hostname()
		if err != nil || host != id.Host {
			return LivenessUnknown
		}
	}
	if id.Boot != "" {
		boot, err := bootID()
		switch {
		case err != nil || boot == "":
			return LivenessUnknown // can't confirm the boot → can't trust the PID
		case boot != id.Boot:
			return LivenessDead // rebooted: the process cannot have survived
		}
	}

	_, _, start, err := procStat(id.PID)
	switch {
	case errors.Is(err, errUnsupported):
		return LivenessUnknown
	case errors.Is(err, errProcessGone):
		return LivenessDead
	case err != nil:
		// Transient/unexpected error: don't claim the process is dead.
		return LivenessUnknown
	}
	if id.Start != "" && start != "" && id.Start != start {
		// Same PID, different start time: the PID was reused by another process.
		return LivenessDead
	}
	return LivenessAlive
}

