func TestDir_StablePerSurfaceAndNeverRealConfigOrCache(t *testing.T) {
	t.Parallel()

	cfg1, ok := Dir("config")
	if !ok {
		t.Fatal("Dir(config) not available under go test")
	}
	cfg2, ok := Dir("config")
	if !ok || cfg2 != cfg1 {
		t.Fatalf("Dir(config) not stable: first %q, second %q (ok=%v)", cfg1, cfg2, ok)
	}

	cache, ok := Dir("cache")
	if !ok {
		t.Fatal("Dir(cache) not available under go test")
	}
	if cache == cfg1 {
		t.Fatalf("surfaces must not share a directory: %q", cache)
	}

	// The invariant is "never the real app locations" — not "never under
	// $HOME" or even "never under ~/.cache": os.MkdirTemp respects TMPDIR,
	// which is commonly set to places like $HOME/.cache/tmp.
	if home, err := os.UserHomeDir(); err == nil {
		for _, realDir := range []string{
			filepath.Join(home, ".config", "entire"),
			filepath.Join(home, ".cache", "entire"),
		} {
			for _, d := range []string{cfg1, cache} {
				if d == realDir || strings.HasPrefix(d, realDir+string(os.PathSeparator)) {
					t.Fatalf("fallback dir %q resolves under the real %q", d, realDir)
				}
			}
		}
	}

	if _, err := os.Stat(cfg1); err != nil {
		t.Fatalf("fallback dir %q was not created: %v", cfg1, err)
	}
}
// Package testdirs provides per-process fallback directories for the CLI's
// on-disk config, cache, and credential surfaces when running inside
// `go test`.
//
// Production code resolves these surfaces relative to the user's home
// directory (~/.config/entire, ~/.cache/entire, the OS keyring). A test that
// forgets to set the explicit override (ENTIRE_CONFIG_DIR, XDG_CACHE_HOME,
// ENTIRE_TOKEN_STORE, ...) would silently read and write the developer's
// real configuration — real auth contexts have been polluted with test
// fixtures this way. Dir gives the resolution functions a safe default under
// test: a throwaway directory under os.TempDir, never the real config/cache

// Package proctree resolves process ancestry with identity that survives PID
// reuse. A ProcessRef is a (PID, start time) pair: equal pairs name the same
// live process instance, because within one boot a recycled PID always comes
// with a new start time. On Linux the unit is boot-relative (clock ticks), so
// a cross-reboot collision is theoretically possible — callers treat ancestry
// as best-effort evidence, never proof. Start-time units are otherwise
// platform-specific (microseconds since epoch on darwin, FILETIME on
// windows); refs are only ever compared against refs recorded on the same
// machine, so the unit never needs to be interpreted, only compared.
package proctree

// ProcessRef identifies one live process instance.
type ProcessRef struct {
	PID       int    `json:"pid"`
	StartTime int64  `json:"start_time"`
	Exe       string `json:"exe,omitempty"`
}

// SameProcess reports whether both refs name the same process instance:
// same PID and same start time. Exe is informational and not compared.
func (r ProcessRef) SameProcess(o ProcessRef) bool {
	return r.PID == o.PID && r.StartTime == o.StartTime && r.PID != 0
}

// Ref resolves the ProcessRef for pid. Errors when the process does not
// exist or the platform refuses introspection.
func Ref(pid int) (ProcessRef, error) {
	ref, _, err := procInfo(pid)
	return ref, err
}

// Ancestors returns the current process's ancestors nearest-first (parent,
// grandparent, ...), at most limit entries. The walk stops at the root
// (PID 0/1), on a cycle, or at the first resolution failure — partial
// results are returned, never an error: callers treat ancestry as
// best-effort evidence. Each level costs one platform introspection call
// (procInfo returns the ref and its parent PID together).
func Ancestors(limit int) []ProcessRef {
	var refs []ProcessRef
	seen := map[int]bool{}
	pid := currentPPID()
	for pid > 1 && len(refs) < limit && !seen[pid] {
		seen[pid] = true
		ref, ppid, err := procInfo(pid)
		if err != nil {
			break
		}
		refs = append(refs, ref)
		pid = ppid
	}
	return refs
}

	}
}

